const LOOK = 0.95;                         // look → headYaw（和 fox1 相同）
const TILT_K = 0.07;
const SHADOW = 'rgb(70,50,25)';
// 轉頭：|headYaw| 小於 TQ_AT 用正面的頭，到 SIDE_AT 之前用 3/4 側，再大用側面
const TQ_AT = 0.32, SIDE_AT = 0.78;

